contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 v) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (v)); require(v <= 1000000000000000000000000000000);
        require(address(this).balance >= v, "insufficient balance");

        uint256 preBalance = address(c).balance;

        bool reverted;
        c.go{value: v}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 postBalance = address(c).balance;

        assert(reverted ? postBalance == preBalance + v : postBalance == 0);
    }

    receive() external payable {}
}

